/bin/bash -lc "cat > .tmp/ascii.py <<'PY'
import numpy as np
F=np.load('source_pixels.npz')['rgb'].astype(int)
chars=' .:-=+*#%@'
def show(t,box,mode):
 x0,y0,x1,y1=box;A=F[t,y0:y1,x0:x1]
 if mode=='rgb':
  R,G,B=A.transpose(2,0,1)
  C=np.full(R.shape,'.',dtype='<U1')
  C[(R>G*1.25)&(R>B*1.15)&(R>100)]='R'
  C[(B>R*1.22)&(B>G*1.12)&(B>100)]='B'
  C[(A.min(2)>210)]='W'
  C[(A.min(2)>170)&(A.max(2)-A.min(2)<45)]='w'
  C[(A.max(2)<100)]='d'
  for r in C: print(''.join(r))
 elif mode=='diff':
  D=np.max(abs(A-F[95,y0:y1,x0:x1]),2)
  for r in D:print(''.join(chars[min(9,int(v)//6)] for v in r))
 elif mode=='lum':
  D=A.mean(2)
  for r in D:print(''.join(chars[min(9,int(v)//26)] for v in r))
for t in [0,20,24,26,30,34,40,50,95]:
 print('\\nFRAME',t,'rgb');show(t,(55,48,180,105),'rgb')
 # print('diff95');show(t,(90,68,130,92),'diff')
PY
python .tmp/ascii.py"

